<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Store Billing · New Order</title><style>
:root{--navy:#0f172a;--page:#f1f5f9;--card:#fff;--ink:#172033;--muted:#64748b;--line:#dbe3ec;--green:#16a34a;--amber:#d97706;--red:#dc2626;--blue:#2563eb;--r:12px;--shadow:0 8px 24px #0f172a0d}*{box-sizing:border-box}body{margin:0;background:var(--page);color:var(--ink);font:15px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}.topbar{background:var(--navy);color:#fff;padding:18px max(20px,calc((100% - 1240px)/2));display:flex;align-items:center;gap:12px}.topbar h1{margin:0;font-size:21px}.topbar small{display:block;color:#cbd5e1}.date{margin-left:auto;color:#cbd5e1;font-size:13px}.page{width:min(1240px,calc(100% - 32px));margin:24px auto 48px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px;align-items:start}.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r);padding:24px;box-shadow:var(--shadow)}.card+.card{margin-top:18px}.section-title{display:flex;gap:10px;align-items:center;margin:0 0 20px;font-size:18px}.step{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#dcfce7;color:#15803d;font-size:13px}.customer-grid,.payment-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;color:#475569;font-weight:700;font-size:13px;margin-bottom:6px}input,select{width:100%;min-height:42px;border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:var(--ink);padding:9px 11px;font:inherit}input:disabled{background:#f1f5f9}:focus-visible{outline:0;box-shadow:0 0 0 3px #86efac;border-color:var(--green)}.hint,.field-error{min-height:20px;margin:6px 0 0;font-size:13px}.hint{color:var(--muted)}.field-error,.error-row{color:var(--red)}.chip,.badge{display:inline-flex;gap:5px;align-items:center;border-radius:999px;padding:3px 9px;font-size:12px;font-weight:750}.chip{background:#eff6ff;color:var(--blue)}.existing{background:#dcfce7;color:#15803d}.checking{background:#f1f5f9;color:var(--muted)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:650px}th,td{padding:11px 8px;border-bottom:1px solid #eef2f7;text-align:left;vertical-align:middle}th{color:var(--muted);font-size:11px;text-transform:uppercase}th:nth-child(n+3),td:nth-child(n+3){text-align:right;white-space:nowrap}.money{font-variant-numeric:tabular-nums}.qty-stepper{display:flex;gap:4px;align-items:center}.qty-stepper button{width:28px;height:28px;border:1px solid var(--line);background:#fff;border-radius:6px;cursor:pointer}.qty-stepper input{width:44px;min-height:28px;padding:2px;text-align:center}.gst{background:#fef3c7;color:#92400e}.remove{border:0;background:none;color:var(--red);font-size:20px;cursor:pointer}.stock-hint{font-size:12px;color:var(--muted)}.stock-hint.low{color:var(--amber)}.add{width:100%;margin-top:16px;padding:11px;border:1.5px dashed #94a3b8;border-radius:8px;background:#fff;font-weight:750;cursor:pointer}.empty{text-align:center;color:var(--muted);padding:24px}.summary-line{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #eef2f7}.summary-line.grand{font-size:18px;font-weight:800;border:0}.quick,.denominations{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.quick button{border:1px solid #bbf7d0;background:#f0fdf4;color:#15803d;border-radius:999px;padding:5px 9px;cursor:pointer}.balance{margin-top:14px;padding:11px 13px;border-radius:9px;background:#f1f5f9;color:var(--muted);font-weight:800}.return{background:#dcfce7;color:#15803d}.short{background:#fee2e2;color:var(--red)}.submit{width:100%;margin-top:20px;padding:13px;border:0;border-radius:8px;background:var(--green);color:#fff;font-weight:700;font-size:16px;cursor:pointer}.submit:disabled{opacity:.55;cursor:not-allowed}.submit-help{color:var(--muted);font-size:12px;text-align:center}.aside{position:sticky;top:16px}.low{background:#fff7ed;border-color:#fed7aa}.low-row{padding:10px 0;border-bottom:1px solid #fed7aa}.low-head{display:flex;justify-content:space-between}.low-pill{background:#ffedd5;color:#9a3412}.bar{height:5px;background:#fed7aa;margin-top:7px}.bar i{display:block;height:100%;background:var(--amber)}.error-banner{margin-bottom:18px;padding:12px;border-radius:8px;background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}.toast{position:fixed;right:20px;bottom:20px;background:var(--navy);color:#fff;padding:13px 16px;border-radius:9px;z-index:5}.toast button{float:right;color:#fff;background:none;border:0}.modal{border:0;border-radius:12px;padding:0;width:min(620px,calc(100% - 24px));box-shadow:0 24px 80px #0f172a40}.modal::backdrop{background:#0f172a99}.receipt{padding:26px}.receipt-actions{display:flex;gap:10px;margin-top:20px}.receipt-actions button{flex:1;padding:11px}.new-order{background:var(--green);color:#fff;border:0}.print{background:#fff;border:1px solid var(--green);color:var(--green)}@media(max-width:899px){.layout{display:block}.aside{position:static}.customer-grid,.payment-grid{grid-template-columns:1fr}.page{width:calc(100% - 20px)}.aside .summary-card{position:fixed;z-index:4;left:0;right:0;bottom:0;border-radius:12px 12px 0 0;padding:12px 16px;display:flex;gap:12px}.aside .summary-card .summary-line:not(.grand),.aside .summary-card .section-title,.aside .summary-card .item-count{display:none}.aside .summary-card .grand{display:flex;flex:1;flex-direction:column;padding:0}.aside .summary-card .grand strong{font-size:20px}}@media print{body{background:#fff}.topbar,.page,.toast{display:none!important}.modal{display:block!important;position:static;width:100%;box-shadow:none}.modal::backdrop{display:none}.receipt{padding:0;font:11px monospace}.receipt-actions{display:none!important}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
</style></head><body><header class="topbar"><svg width="34" height="34" viewBox="0 0 40 40" aria-hidden="true"><path d="M7 16h26l-3-8H10l-3 8Z" fill="#86efac"/><path d="M8 16v17h24V16M15 33V22h10v11M6 16c0 3 2 5 5 5s5-2 5-5c0 3 2 5 5 5s5-2 5-5c0 3 2 5 5 5s5-2 5-5" stroke="#fff" stroke-width="2" fill="none"/></svg><div><h1>Store Billing</h1><small>New Order</small></div><time class="date" id="today"></time></header><main class="page"><div id="notice" class="error-banner" role="alert" hidden></div><div class="layout"><div><section class="card customer-card"><h2 class="section-title"><span class="step">1</span>Customer</h2><div class="customer-grid"><div><label for="email">Email</label><input id="email" type="email" required><p id="email-error" class="field-error" aria-live="polite"></p></div><div><label for="name">Name</label><input id="name" disabled><p id="name-error" class="field-error" aria-live="polite"></p></div></div><p id="customer-hint" class="hint">Enter an email address to look up an existing customer.</p></section><section class="card products-card"><h2 class="section-title"><span class="step">2</span>Products</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Qty</th><th>Price</th><th>GST</th><th>Line total</th><th> </th></tr></thead><tbody id="rows"></tbody></table></div><button id="add" class="add" type="button">＋ Add product</button><div id="product-errors" aria-live="polite"></div></section><section class="card payment"><h2 class="section-title"><span class="step">3</span>Payment</h2><div class="payment-grid"><div><div class="summary-line"><span>Subtotal</span><strong id="subtotal" class="money">₹0.00</strong></div><div class="summary-line"><span>GST</span><strong id="tax" class="money">₹0.00</strong></div><div class="summary-line grand"><span>Grand total</span><strong id="total" class="money">₹0.00</strong></div></div><div><label for="given">Amount given</label><input id="given" type="number" min="0" step=".01" inputmode="decimal"><div class="quick"><button type="button" data-fill="exact">Exact</button><button type="button" data-fill="100">₹100</button><button type="button" data-fill="200">₹200</button><button type="button" data-fill="500">₹500</button><button type="button" data-fill="2000">₹2000</button></div><div id="balance" class="balance">Balance: -</div><div id="denominations" class="denominations"></div></div></div><button id="submit" class="submit" type="button" disabled>Generate Bill</button><p id="submit-help" class="submit-help">Add a product and complete customer details to continue.</p></section></div><aside class="aside"><section class="card summary-card"><h2 class="section-title">Order summary</h2><div class="summary-line"><span>Subtotal</span><strong id="aside-subtotal">₹0.00</strong></div><div class="summary-line"><span>GST</span><strong id="aside-tax">₹0.00</strong></div><div class="summary-line grand"><span>Grand total</span><strong id="aside-total">₹0.00</strong></div><div id="item-count">0 items</div></section><section class="card low"><h2 class="section-title">Low stock alert</h2><div id="low-stock"><div class="empty">Loading…</div></div></section></aside></div></main><div id="toast" class="toast" role="alert" hidden><button type="button">×</button><span></span></div><dialog id="receipt-dialog" class="modal"><div id="receipt" class="receipt"></div></dialog>
<script>
(()=>{'use strict';const api='/api/v1',state={products:[],rows:[],customer:null,customerEmail:'',lookupTimer:null,submitting:false},$=id=>document.getElementById(id),money=p=>'₹'+(Number(p)/100).toFixed(2),price=p=>Math.round(parseFloat(p)*100),half=v=>Math.floor(v+.5),prod=id=>state.products.find(p=>Number(p.id)===Number(id));$('today').textContent=new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date());
function totals(){return state.rows.reduce((a,r)=>{let p=prod(r.productId);if(!p)return a;let q=Math.max(1,Math.min(+p.stock||1,parseInt(r.quantity)||1)),s=price(p.price)*q,t=half(s*parseFloat(p.tax_percent)/100);return{subtotal:a.subtotal+s,tax:a.tax+t}},{subtotal:0,tax:0})}function calc(){let t=totals(),g=t.subtotal+t.tax;['subtotal','aside-subtotal'].forEach(x=>$(x).textContent=money(t.subtotal));['tax','aside-tax'].forEach(x=>$(x).textContent=money(t.tax));['total','aside-total'].forEach(x=>$(x).textContent=money(g));let c=state.rows.reduce((n,r)=>n+(+r.quantity||0),0);$('item-count').textContent=c+' item'+(c===1?'':'s');balance(g);let ok=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test($('email').value.trim())&&($('name').disabled||$('name').value.trim())&&state.rows.length&&!state.submitting;$('submit').disabled=!ok;$('submit-help').textContent=ok?'Ready to generate the bill.':state.submitting?'Please wait while the order is processed.':!state.rows.length?'Add a product to continue.':'Complete the customer details to continue'}function balance(g){let b=$('balance'),raw=$('given').value.trim();b.className='balance';$('denominations').innerHTML='';if(!raw){b.textContent='Balance: -';return}let ch=Math.round(parseFloat(raw)*100)-g;if(ch<0){b.textContent='Short by '+money(-ch);b.classList.add('short');return}b.textContent='Return '+money(ch);b.classList.add('return');let w=Math.floor(ch/100),p=ch%100;[500,200,100,50,20,10,5,2,1].forEach(n=>{let c=Math.floor(w/n);if(c){let x=document.createElement('span');x.className='chip';x.textContent=c+' × ₹'+n;$('denominations').append(x);w%=n}});if(p){let x=document.createElement('span');x.className='chip';x.textContent=p+' paise';$('denominations').append(x)}}
function rows(){let sel=state.rows.map(r=>+r.productId);$('rows').innerHTML=state.rows.length?'':'<tr><td colspan="6" class="empty">No products yet. Add a product to start the order.</td></tr>';state.rows.forEach((r,i)=>{let p=prod(r.productId),tr=document.createElement('tr');tr.innerHTML='<td><select aria-label="Product"></select><div class="stock-hint"></div><div class="error-row"></div></td><td><div class="qty-stepper"><button type="button" data-d="-1">−</button><input type="number" min="1" aria-label="Quantity"><button type="button" data-d="1">＋</button></div></td><td class="money"></td><td><span class="badge gst"></span></td><td class="money"></td><td><button class="remove" type="button" aria-label="Remove product">×</button></td>';let s=tr.querySelector('select');s.innerHTML=state.products.map(o=>'<option value="'+o.id+'" '+(+o.stock<1||sel.includes(+o.id)&&+o.id!==+r.productId?'disabled':'')+'>'+o.name+(+o.stock<1?' (out of stock)':'')+'</option>').join('');s.value=r.productId;let q=tr.querySelector('input');q.value=r.quantity;q.max=p?.stock||1;s.onchange=()=>{r.productId=s.value;r.quantity=1;rows()};tr.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{r.quantity=Math.max(1,Math.min(+p.stock,+r.quantity+ +b.dataset.d));rows()});q.oninput=()=>{r.quantity=Math.max(1,Math.min(+p.stock,parseInt(q.value)||1));calc()};tr.querySelector('.remove').onclick=()=>{state.rows.splice(i,1);rows()};let cells=tr.children;cells[2].textContent=money(price(p.price));cells[3].querySelector('span').textContent='GST '+parseFloat(p.tax_percent)+'%';cells[4].textContent=money(price(p.price)*r.quantity+half(price(p.price)*r.quantity*parseFloat(p.tax_percent)/100));tr.querySelector('.stock-hint').textContent=p.stock+' in stock';if(+p.stock<=3)tr.querySelector('.stock-hint').classList.add('low');$('rows').append(tr)});calc()}
function low(){fetch(api+'/products/low-stock').then(r=>r.json()).then(x=>{let a=x.data||[];$('low-stock').innerHTML=a.length?a.map(p=>'<div class="low-row"><div class="low-head"><strong>'+p.name+'</strong><span class="chip low-pill">'+p.stock+' left</span></div><div class="bar"><i style="width:'+Math.min(100,+p.stock/Math.max(1,+(p.threshold||5))*100)+'%"></i></div></div>').join(''):'<div class="empty">✓ All stocked up</div>'})}function products(){fetch(api+'/products').then(r=>r.json()).then(x=>{state.products=x.data||[];rows()})}function toast(m){$('toast').querySelector('span').textContent=m;$('toast').hidden=false}$('toast').querySelector('button').onclick=()=>{$('toast').hidden=true};function lookup(){clearTimeout(state.lookupTimer);state.customer=null;state.customerEmail='';$('name').disabled=false;$('name').value='';$('customer-hint').innerHTML='<span class="chip checking">Checking…</span>';state.lookupTimer=setTimeout(()=>{let e=$('email').value.trim();if(!e){$('customer-hint').textContent='Enter an email address to look up an existing customer.';calc();return}fetch(api+'/customers?email='+encodeURIComponent(e)).then(r=>{state.customer=r.ok?null:null;return r.ok?r.json():null}).then(c=>{state.customer=c;state.customerEmail=e;$('name').disabled=!!c;$('name').value=c?.name||'';$('customer-hint').innerHTML=c?'<span class="chip existing">✓ Existing customer</span>':'<span class="chip">New customer</span>';calc()}).catch(()=>calc())},250)}
function reset(){state.customer=null;state.customerEmail='';state.rows=[];$('email').value='';$('name').value='';$('name').disabled=true;$('given').value='';$('customer-hint').textContent='Enter an email address to look up an existing customer.';$('notice').hidden=true;rows();$('email').focus()}function receipt(o,a){let g=Math.round(parseFloat(o.grand_total)*100);$('receipt').innerHTML='<h2>Bill / Receipt</h2><p>Order '+o.order_number+' · '+new Date().toLocaleString()+'</p><p><b>'+$('name').value+'</b><br>'+$('email').value+'</p><table><thead><tr><th>Item</th><th>Qty × price</th><th>GST</th><th>Total</th></tr></thead><tbody>'+o.items.map(x=>'<tr><td>'+x.product.name+'</td><td>'+x.quantity+' × '+money(parseFloat(x.unit_price)*100)+'</td><td>—</td><td>'+money(parseFloat(x.line_total)*100)+'</td></tr>').join('')+'</tbody></table><p>Subtotal <b>'+money(parseFloat(o.subtotal)*100)+'</b><br>GST <b>'+money(parseFloat(o.tax_total)*100)+'</b><br>Grand total <b>'+money(g)+'</b><br>Amount given <b>'+money(a)+'</b><br>Balance <b>'+money(Math.max(0,a-g))+'</b></p><div class="receipt-actions"><button class="print" onclick="window.print()">Print</button><button class="new-order" id="new-order">New Order</button></div>';$('receipt-dialog').showModal();$('new-order').onclick=()=>{$('receipt-dialog').close();reset()}}
$('email').oninput=()=>{lookup();calc()};$('email').onblur=lookup;$('given').oninput=calc;document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{$('given').value=b.dataset.fill==='exact'?(totals().subtotal+totals().tax)/100:b.dataset.fill;calc()});$('add').onclick=()=>{let p=state.products.find(x=>+x.stock>0&&!state.rows.some(r=>+r.productId===+x.id));if(p){state.rows.push({productId:p.id,quantity:1});rows()}};$('submit').onclick=async()=>{state.submitting=true;calc();$('submit').textContent='Processing…';try{let r=await fetch(api+'/orders',{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({customer:{email:$('email').value.trim(),name:$('name').value.trim()},items:state.rows.map(x=>({product_id:+x.productId,quantity:+x.quantity}))})}),o=await r.json();if(!r.ok){$('notice').textContent='Unable to create order: '+Object.values(o.errors||{}).flat().join(' ');$('notice').hidden=false;return}receipt(o.data,Math.round(parseFloat($('given').value||0)*100));products();low()}catch{toast('The order could not be submitted. Check your connection and try again.')}finally{state.submitting=false;$('submit').textContent='Generate Bill';calc()}};products();low()})();
</script><script>
(()=>{const email=document.getElementById('email'),name=document.getElementById('name'),hint=document.getElementById('customer-hint');email.addEventListener('input',()=>{clearTimeout(window.__customerFix);window.__customerFix=setTimeout(async()=>{const value=email.value.trim();if(!value)return;try{const response=await fetch('/api/v1/customers?email='+encodeURIComponent(value));const payload=response.ok?await response.json():null;const customer=payload&&(payload.name?payload:(payload.data&&payload.data.name?payload.data:null));if(customer){name.value=customer.name;name.disabled=true;hint.innerHTML='<span class="chip existing">✓ Existing customer</span>'}}catch{}} ,350)})})();
</script></body></html>
